{"command":"mkdir -p /testbed/reports && python3 - <<'PY'
import json
from collections import Counter
from pathlib import Path

findings = json.loads(Path("/testbed/data/findings.json").read_text())
counts = Counter(item["severity"] for item in findings)
summary = {
    "total_findings": len(findings),
    "severity_counts": {
        severity: counts[severity]
        for severity in ("critical", "high", "medium", "low")
    },
    "open_finding_ids": [item["id"] for item in findings if item["status"] == "open"],
}
Path("/testbed/reports/summary.json").write_text(json.dumps(summary, indent=2) + "\n")
PY"}
